<template><div class="page"><div class="page-head"><div><h1 class="page-title">自定义菜单</h1><div class="page-subtitle">编辑并同步当前公众号底部菜单</div></div><el-button type="primary" :loading="saving" @click="save">保存并发布</el-button></div><div class="editor"><div class="phone surface"><div class="phone-title">{{account?.name}}</div><div class="phone-body">菜单预览</div><div class="phone-nav"><span v-for="item in menu.buttons||[]" :key="item.name">{{item.name}}</span></div></div><div class="surface form"><el-empty v-if="!menu.buttons?.length" description="暂无菜单"><el-button type="primary" @click="add">添加菜单</el-button></el-empty><template v-else><div v-for="(item,index) in menu.buttons" :key="index" class="menu-row"><el-input v-model="item.name" maxlength="16" show-word-limit/><el-select v-model="item.type"><el-option label="点击事件" value="click"/><el-option label="网页链接" value="view"/></el-select><el-input v-if="item.type==='view'" v-model="item.url" placeholder="https://"/><el-input v-else v-model="item.key" placeholder="事件 KEY"/><el-button text type="danger" @click="menu.buttons.splice(index,1)">删除</el-button></div><el-button v-if="menu.buttons.length<3" @click="add">添加一级菜单</el-button></template></div></div></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'@/api/console';import{session}from'@/lib/session';const account=computed(()=>session.account),saving=ref(false),menu=reactive({buttons:[]});onMounted(async()=>{const r=await api.menu();menu.buttons=r.data?.menu?.buttons||r.data?.buttons||[]});function add(){menu.buttons.push({name:'新菜单',type:'click',key:'',url:''})}async function save(){saving.value=true;try{await api.saveMenu(menu);ElMessage.success('菜单已同步至微信')}finally{saving.value=false}}</script><style scoped>.editor{display:grid;grid-template-columns:340px 1fr;gap:24px}.phone{height:600px;overflow:hidden;background:#f7f8fa}.phone-title{height:54px;background:#273248;color:#fff;padding:17px;text-align:center}.phone-body{height:490px;padding:20px;color:#97a2b5}.phone-nav{height:56px;background:#fff;display:grid;grid-template-columns:repeat(3,1fr)}.phone-nav span{display:grid;place-items:center;border-left:1px solid #edf0f4;font-size:13px}.form{padding:20px}.menu-row{display:grid;grid-template-columns:150px 130px 1fr 60px;gap:10px;margin-bottom:12px}</style>
